     ///
     /// # Parameters
     ///
     /// - `raw_addr`: The raw value.
     ///
     /// # Returns
     ///
     /// - `Ok(Self)`: The new address.
     /// - `Err(Error::BadAddress)`: If the provided address is invalid.
     ///
     fn from_raw_value(raw_addr: usize) -> Result<Self, Error> {
         Self::from_address(T::from_raw_value(raw_addr)?)
